('original:math--geometry--triangle-congruence:math--geometry--triangle-congruence--1',1,'{"question":"What does it mean for two triangles to be congruent?","choices":["Only their areas are equal","Corresponding sides and angles have equal measures","Only their angles are equal","Their side lengths share any scale factor"],"answer":1,"explanation":""}'::jsonb,'eb3e556fbf339ff165cf6dfc5d24c2a7','official',NULL,NULL,'Triangle Congruence'),
('original:math--geometry--triangle-congruence:math--geometry--triangle-congruence--2',1,'{"question":"Which condition is the SSS congruence criterion?","choices":["Three pairs of corresponding sides are equal","Three pairs of corresponding angles are equal","Two sides and any angle are equal","One side and one angle are equal"],"answer":0,"explanation":""}'::jsonb,'273e1e31a823280b1588842f7431743c','official',NULL,NULL,'Triangle Congruence'),
('original:math--geometry--triangle-congruence:math--geometry--triangle-congruence--3',1,'{"question":"Which condition is the SAS congruence criterion?","choices":["Two corresponding angles and any side are equal","Three corresponding angles are equal","Two corresponding sides and a nonincluded angle are equal","Two corresponding sides and their included angle are equal"],"answer":3,"explanation":""}'::jsonb,'c95997a9469a61d8e70bcbf9c67ed8b6','official',NULL,NULL,'Triangle Congruence'),
('original:math--geometry--triangle-congruence:math--geometry--triangle-congruence--4',1,'{"question":"What does ASA require?","choices":["Three corresponding angles","Two corresponding sides and the included angle","Two corresponding angles and the included side","One corresponding angle and one side"],"answer":2,"explanation":""}'::jsonb,'e2ad63ad03d5c110162a9c6b75b5d03b','official',NULL,NULL,'Triangle Congruence'),
('original:math--geometry--triangle-congruence:math--geometry--triangle-congruence--5',1,'{"question":"Why is AAA alone insufficient to prove congruence?","choices":["It never establishes similarity","It establishes shape but not size","It requires a right angle","It forces all sides to be equal"],"answer":1,"explanation":""}'::jsonb,'b804e60ce8dab414960d510c03ccfca9','official',NULL,NULL,'Triangle Congruence'),
('original:math--geometry--triangle-congruence:math--geometry--triangle-congruence--6',1,'{"question":"Which special criterion applies to right triangles?","choices":["Hypotenuse and one corresponding leg are equal","Any two corresponding angles are equal","Only the hypotenuses are equal","Only the areas are equal"],"answer":0,"explanation":""}'::jsonb,'5e5b99abbe0bf09450faf79f125a8cf8','official',NULL,NULL,'Triangle Congruence'),
('original:math--geometry--triangle-congruence:math--geometry--triangle-congruence--7',1,'{"question":"In triangle ABC congruent to triangle DEF, which side corresponds to AB?","choices":["EF","DF","FE","DE"],"answer":3,"explanation":""}'::jsonb,'b7e93dbdd362aabacf0f49d4fcedbcac','official',NULL,NULL,'Triangle Congruence'),
('original:math--geometry--triangle-congruence:math--geometry--triangle-congruence--8',1,'{"question":"What is an included angle between two sides?","choices":["Any angle outside the triangle","The angle opposite both sides","The angle formed where those sides meet","An angle that must measure 90 degrees"],"answer":2,"explanation":""}'::jsonb,'1b50a51a457acec026b75b9876ae25bd','official',NULL,NULL,'Triangle Congruence'),
('original:math--geometry--triangle-congruence:math--geometry--triangle-congruence--9',1,'{"question":"Two triangles have side lengths 4, 5, and 6 units. Why must they be congruent?","choices":["The AAA criterion proves congruence","The SSS criterion applies","Equal perimeters always prove congruence","Any two triangles with a 4-unit side are congruent"],"answer":1,"explanation":""}'::jsonb,'6575f46b7d67b65e6dfebed9e2de8299','official',NULL,NULL,'Triangle Congruence'),
('original:math--geometry--triangle-congruence:math--geometry--triangle-congruence--10',1,'{"question":"Two triangles have angles 40°, 60°, and 80° but different side lengths. What follows?","choices":["They are similar but not congruent","They must be congruent","They cannot be similar","They must be right triangles"],"answer":0,"explanation":""}'::jsonb,'5082d91a21ddb921038f5085334b25d0','official',NULL,NULL,'Triangle Congruence'),
('original:math--geometry--triangle-congruence:math--geometry--triangle-congruence--11',1,'{"question":"Triangle ABC is congruent to triangle RST. If angle B is 55°, what is angle S?","choices":["35°","125°","110°","55°"],"answer":3,"explanation":""}'::jsonb,'c6a78f86e863c51738405333d3399fed','official',NULL,NULL,'Triangle Congruence'),
('original:math--geometry--triangle-congruence:math--geometry--triangle-congruence--12',1,'{"question":"Which information is generally insufficient to prove two triangles congruent?","choices":["Three corresponding sides","Two angles and their included side","Two sides and a nonincluded angle","Two sides and their included angle"],"answer":2,"explanation":""}'::jsonb,'fe970094601e593a4ecef1f4785ac39e','official',NULL,NULL,'Triangle Congruence'),
('original:math--geometry--triangle-congruence:math--geometry--triangle-congruence--13',1,'{"question":"Two right triangles have hypotenuses of 13 units and one leg of 5 units. Which conclusion is justified?","choices":["They are only similar because their sizes may differ","They are congruent by the hypotenuse-leg criterion","They are congruent by AAA alone","Their other legs may have different lengths"],"answer":1,"explanation":""}'::jsonb,'5e4480870b3aefc46cbd8fc9e43ac3a5','official',NULL,NULL,'Triangle Congruence'),
('original:math--geometry--triangle-congruence:math--geometry--triangle-congruence--14',1,'{"question":"If triangles are congruent, what can be concluded about their perimeters?","choices":["Their perimeters are equal","Their perimeters differ by a factor of 2","Only their longest sides affect their perimeters","Their perimeters must be whole numbers"],"answer":0,"explanation":""}'::jsonb,'9048bdb632f210d758e0e19be4129378','official',NULL,NULL,'Triangle Congruence'),
('original:math--geometry--triangle-congruence:math--geometry--triangle-congruence--15',1,'{"question":"Why does AAS prove congruence even though the known side is not between the two known angles?","choices":["The known side becomes a hypotenuse","All three sides must be given first","AAS applies only to equilateral triangles","The third angle is fixed by the triangle angle sum"],"answer":3,"explanation":""}'::jsonb,'115a5c6f0ae2a67848f8f42a2b7eeaab','official',NULL,NULL,'Triangle Congruence'),
('original:math--geometry--triangle-congruence:math--geometry--triangle-congruence--16',1,'{"question":"Triangles ABC and ADC share side AC. If AB = AD and BC = DC, which criterion proves their congruence?","choices":["ASA","AAA","SSS","Hypotenuse-leg only"],"answer":2,"explanation":""}'::jsonb,'247180bff731b8d181b5ecbaa0746f1e','official',NULL,NULL,'Triangle Congruence')
