('original:math--geometry--triangle-congruence:math--geometry--triangle-congruence--17',1,'{"question":"Triangles PQR and XYZ have PQ = XY, PR = XZ, and angle P = angle X. Which criterion applies?","choices":["ASA","SAS","AAS","AAA"],"answer":1,"explanation":""}'::jsonb,'4e39d56b3d92eda2772c83a591acdf87','official',NULL,NULL,'Triangle Congruence'),
