('original:math--geometry--similarity-and-scale-factors:math--geometry--similarity-and-scale-factors--1',1,'{"question":"What must be true of corresponding angles in similar triangles?","choices":["They differ by the scale factor","Their measures add to 180°","They are equal in measure","They must all be acute"],"answer":2,"explanation":""}'::jsonb,'5be7d79763a3b2783c9a48d737627970','official',NULL,NULL,'Similarity and Scale Factors'),
