('original:math--geometry--similarity-and-scale-factors:math--geometry--similarity-and-scale-factors--3',1,'{"question":"A side grows from 4 units to 12 units. What is the scale factor from the original to the image?","choices":["3","8","1/3","16"],"answer":0,"explanation":""}'::jsonb,'8f774282b701aa987ef7886f21f4036f','official',NULL,NULL,'Similarity and Scale Factors'),
