('original:math--statistics-probability--two-way-tables-and-conditional-probability:math--statistics-probability--two-way-tables-and-conditional-probability--7',1,'{"question":"In a survey of 100 students, 18 are both ninth graders and bus riders. What is their joint relative frequency?","choices":["0.82","0.50","0.09","0.18"],"answer":3,"explanation":""}'::jsonb,'10a5b359eecace397bc91fc87f581bbf','official',NULL,NULL,'Two-Way Tables and Conditional Probability'),
('original:math--statistics-probability--two-way-tables-and-conditional-probability:math--statistics-probability--two-way-tables-and-conditional-probability--8',1,'{"question":"Why can P(A given B) differ from P(B given A)?","choices":["Both must use the entire sample as denominator","Conditional probabilities are always complementary","The conditions may select groups of different sizes","The order of the labels never changes the denominator"],"answer":2,"explanation":""}'::jsonb,'141f8495cfc56135d22c02f491762eaf','official',NULL,NULL,'Two-Way Tables and Conditional Probability'),
('original:math--statistics-probability--two-way-tables-and-conditional-probability:math--statistics-probability--two-way-tables-and-conditional-probability--9',1,'{"question":"A table shows 30 bus riders and 20 walkers in grade 9. Among randomly selected ninth graders, what is the probability of walking?","choices":["3/5","2/5","2/3","1/5"],"answer":1,"explanation":""}'::jsonb,'14c2575453db9a1435365fd55f0b3b39','official',NULL,NULL,'Two-Way Tables and Conditional Probability'),
('original:math--statistics-probability--two-way-tables-and-conditional-probability:math--statistics-probability--two-way-tables-and-conditional-probability--10',1,'{"question":"A table lists 24 club members who volunteer and 16 club members who do not. What fraction of club members volunteer?","choices":["3/5","2/5","3/2","1/4"],"answer":0,"explanation":""}'::jsonb,'b4b69451b97779753e3bab68d6dcf1bc','official',NULL,NULL,'Two-Way Tables and Conditional Probability'),
('original:math--statistics-probability--two-way-tables-and-conditional-probability:math--statistics-probability--two-way-tables-and-conditional-probability--11',1,'{"question":"A school has 60 ninth graders and 40 tenth graders. Of its 30 athletes, 18 are ninth graders. What is P(ninth grader given athlete)?","choices":["3/10","9/50","2/5","3/5"],"answer":3,"explanation":""}'::jsonb,'5283aad87f2f5a13a96e306ee8d4738d','official',NULL,NULL,'Two-Way Tables and Conditional Probability'),
('original:math--statistics-probability--two-way-tables-and-conditional-probability:math--statistics-probability--two-way-tables-and-conditional-probability--12',1,'{"question":"A school has 60 ninth graders and 40 tenth graders. Of its 30 athletes, 18 are ninth graders. What is P(athlete given ninth grader)?","choices":["3/5","9/50","3/10","1/2"],"answer":2,"explanation":""}'::jsonb,'ab1302e08a1cea9841ab16495c69a44a','official',NULL,NULL,'Two-Way Tables and Conditional Probability'),
('original:math--statistics-probability--two-way-tables-and-conditional-probability:math--statistics-probability--two-way-tables-and-conditional-probability--13',1,'{"question":"Which comparison helps identify an association between grade level and club membership?","choices":["Compare only the raw grade totals","Compare club-membership proportions within each grade","Compare the highest and lowest student ages","Compare the sum of every marginal total"],"answer":1,"explanation":""}'::jsonb,'87adb12b2110f273c922ebc978d3b71d','official',NULL,NULL,'Two-Way Tables and Conditional Probability'),
('original:math--statistics-probability--two-way-tables-and-conditional-probability:math--statistics-probability--two-way-tables-and-conditional-probability--14',1,'{"question":"A table shows that 75% of one group and 25% of another prefer online reading. What does this suggest?","choices":["An association between group and reading preference","Proof that group membership causes the preference","Identical conditional distributions","A calculation error because percentages must be equal"],"answer":0,"explanation":""}'::jsonb,'7ee84b45f95ece0d5021542d3882702f','official',NULL,NULL,'Two-Way Tables and Conditional Probability'),
('original:math--statistics-probability--two-way-tables-and-conditional-probability:math--statistics-probability--two-way-tables-and-conditional-probability--15',1,'{"question":"A row contains 14 students who play sports and 21 who do not. What is the row total?","choices":["7","294","21","35"],"answer":3,"explanation":""}'::jsonb,'fd8c930c0c96638b012ae1ce2d9499b0','official',NULL,NULL,'Two-Way Tables and Conditional Probability'),
('original:math--statistics-probability--two-way-tables-and-conditional-probability:math--statistics-probability--two-way-tables-and-conditional-probability--16',1,'{"question":"A survey has 80 students. Of 50 students with pets, 20 prefer hiking. Of 30 without pets, 15 prefer hiking. Which group has a higher hiking-preference rate?","choices":["Students with pets: 40% versus 50%","Both groups: 25%","Students without pets: 50% versus 40%","Students with pets: 20% versus 15%"],"answer":2,"explanation":""}'::jsonb,'d7d625229d99a1bf06440b55a27ae29d','official',NULL,NULL,'Two-Way Tables and Conditional Probability')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:math--statistics-probability--two-way-tables-and-conditional-probability:math--statistics-probability--two-way-tables-and-conditional-probability--17',1,'{"question":"Among 30 students who take art, 12 take music. Among 70 who do not take art, 28 take music. Which conclusion is supported by these data?","choices":["Art students are twice as likely to take music","The music-taking rate is the same in both groups","Not taking art causes students to take music","The two groups contain the same number of students"],"answer":1,"explanation":""}'::jsonb,'df804ab68c73e9ac0dd3efe7d9cf2463','official',NULL,NULL,'Two-Way Tables and Conditional Probability'),
('original:math--statistics-probability--two-way-tables-and-conditional-probability:math--statistics-probability--two-way-tables-and-conditional-probability--18',1,'{"question":"A survey lists 25 readers who exercise and 15 readers who do not. It also lists 10 nonreaders who exercise and 10 who do not. What is P(reader given exercises)?","choices":["5/7","2/3","5/12","3/8"],"answer":0,"explanation":""}'::jsonb,'1c583207ee32d214746724f7cdac7f32','official',NULL,NULL,'Two-Way Tables and Conditional Probability'),
('original:math--statistics-probability--two-way-tables-and-conditional-probability:math--statistics-probability--two-way-tables-and-conditional-probability--19',1,'{"question":"At a school, 20 of 50 students in a morning class and 10 of 25 in an afternoon class bring lunch. What can be concluded?","choices":["The morning rate is twice the afternoon rate","The afternoon rate is twice the morning rate","The rates are 20% and 10%","Both classes have a 40% lunch-bringing rate"],"answer":3,"explanation":""}'::jsonb,'6d4e90513e2df7b4ba508af9cf1b2182','official',NULL,NULL,'Two-Way Tables and Conditional Probability'),
('original:math--statistics-probability--two-way-tables-and-conditional-probability:math--statistics-probability--two-way-tables-and-conditional-probability--20',1,'{"question":"A table has cells 8 and 12 in its first row and 15 and 5 in its second row. What is the grand total?","choices":["20","23","40","17"],"answer":2,"explanation":""}'::jsonb,'57ad7d92cb77dc87edd7cb80420e5125','official',NULL,NULL,'Two-Way Tables and Conditional Probability'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--1',1,'{"question":"When are two events independent?","choices":["They can never occur together","They have equal probabilities","Knowing one occurred does not change the probability of the other","Their probabilities add to 1"],"answer":2,"explanation":""}'::jsonb,'7a90daf6febc2671a2f08e47f6faadfb','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--2',1,'{"question":"When are two events dependent?","choices":["They must occur at the same time","Knowing one occurred changes the probability of the other","They must have different names","They each have probability 1/2"],"answer":1,"explanation":""}'::jsonb,'b96b2282df77266fa030ffc08ce008be','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--3',1,'{"question":"Which formula applies to independent events A and B?","choices":["P(A and B) = P(A)P(B)","P(A and B) = P(A) + P(B)","P(A and B) = P(A) − P(B)","P(A and B) = P(A)/P(B)"],"answer":0,"explanation":""}'::jsonb,'bb24b62e692bb8aac93790bef9d408b0','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--4',1,'{"question":"What is P(A given B) when A and B are independent and P(B) > 0?","choices":["P(B)","0","1","P(A)"],"answer":3,"explanation":""}'::jsonb,'e75b5d29dd3b16dbec428b3ee68f8ce2','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--5',1,'{"question":"Which experiment normally makes successive color draws independent?","choices":["Drawing without replacement","Removing every ball of the first color drawn","Drawing from a mixed bag with replacement and remixing","Drawing only after changing the bag''s contents"],"answer":2,"explanation":""}'::jsonb,'d16e918976d4d11cd7eb6b8c2baa63aa','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--6',1,'{"question":"A fair coin and fair six-sided die are used independently. What is the probability of heads and a 6?","choices":["1/2","1/12","1/6","2/3"],"answer":1,"explanation":""}'::jsonb,'5e3f27e03f9502f6a1c7933c05ca5504','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--7',1,'{"question":"Two events have P(A) = P(B) = 0.4 and P(A and B) = 0.16. What can be concluded?","choices":["The events are independent","The events are mutually exclusive","The events have no common outcomes","The events are complementary"],"answer":0,"explanation":""}'::jsonb,'b4675f5d26dc1842f6d9debe7344c0f5','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--8',1,'{"question":"Why are successive draws without replacement usually dependent?","choices":["The first draw changes the names of the colors","The total number of original outcomes is infinite","Both draws must produce the same color","The first draw changes the contents for the second draw"],"answer":3,"explanation":""}'::jsonb,'d5ec047e0c0ffa571693b84ace324c6a','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--9',1,'{"question":"A bag has 3 red and 2 blue balls. If a red ball is drawn without replacement, what is the probability the next ball is red?","choices":["3/5","2/5","1/2","1/5"],"answer":2,"explanation":""}'::jsonb,'4f246af6f34f675937a1ff19734949a7','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--10',1,'{"question":"A bag has 4 green and 6 yellow balls. After drawing and replacing a green ball and remixing, what is the probability the next ball is green?","choices":["1/3","2/5","4/9","3/10"],"answer":1,"explanation":""}'::jsonb,'1a33578c3fa064885f5e4a36fb9e09fd','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--11',1,'{"question":"Why are two mutually exclusive events with positive probabilities not independent?","choices":["The occurrence of one makes the other''s probability zero","They always occur together","Their probabilities must both be 1/2","Their combined probability must exceed 1"],"answer":0,"explanation":""}'::jsonb,'fb70b10edcf696b0ba1b9e0ddbdd77af','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--12',1,'{"question":"If P(A) = 0.3 and P(A given B) = 0.6, with P(B) > 0, what follows?","choices":["A and B are independent","A and B are mutually exclusive","A and B must have equal probabilities","A and B are dependent"],"answer":3,"explanation":""}'::jsonb,'3dbb5a6e85cd6a2f5074939be23802ea','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--13',1,'{"question":"For independent events, P(A) = 0.2 and P(B) = 0.5. What is P(A and B)?","choices":["0.7","0.3","0.1","0.4"],"answer":2,"explanation":""}'::jsonb,'9e5535b714a34b8e9590ef1d062b9217','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--14',1,'{"question":"What formula is valid for any events A and B with P(A) > 0?","choices":["P(A and B) = P(A) + P(B given A)","P(A and B) = P(A)P(B given A)","P(A and B) = P(B given A) − P(A)","P(A and B) = P(A)/P(B given A)"],"answer":1,"explanation":""}'::jsonb,'892e2dbab349053a08ee769b26dfb744','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--15',1,'{"question":"Does equal probability by itself prove two events independent?","choices":["No; independence concerns whether one changes the other''s probability","Yes; every pair with equal probabilities is independent","Yes; equal probabilities imply mutual exclusivity","No; independent events must have unequal probabilities"],"answer":0,"explanation":""}'::jsonb,'498cd5307489705e42a7a8e7040b93e1','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--16',1,'{"question":"Three bulbs independently have a 0.9 probability of working. What is the probability all three work?","choices":["0.9","0.3","0.81","0.729"],"answer":3,"explanation":""}'::jsonb,'368d60db40c5ccdaff0c30cd634bec39','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--17',1,'{"question":"A bag has 5 black and 5 white balls. Two balls are drawn without replacement. What is the probability both are black?","choices":["1/4","1/2","2/9","5/9"],"answer":2,"explanation":""}'::jsonb,'1e7eda03c20abd5068e134d612187d80','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--18',1,'{"question":"Two independent machines each have a 0.1 probability of failure. What is the probability neither fails?","choices":["0.01","0.81","0.2","0.9"],"answer":1,"explanation":""}'::jsonb,'a0dd69cf20a86f2ecebd493d02b6d704','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--19',1,'{"question":"Events A and B have P(A) = 1/2, P(B) = 1/3, and P(A and B) = 1/6. What does this show?","choices":["They are independent because the joint probability equals the product","They are mutually exclusive because 1/6 is small","They are dependent because their probabilities differ","They are impossible because the probabilities do not sum to 1"],"answer":0,"explanation":""}'::jsonb,'23735067325f3c28636f771c44308c11','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--independent-and-dependent-events:math--statistics-probability--independent-and-dependent-events--20',1,'{"question":"A bag has 2 red and 3 blue balls. Two draws are made without replacement. What is P(first red and second blue)?","choices":["6/25","1/5","1/2","3/10"],"answer":3,"explanation":""}'::jsonb,'633fb77edb763ad1f00c858365b71e49','official',NULL,NULL,'Independent and Dependent Events'),
('original:math--statistics-probability--permutations-and-combinations:math--statistics-probability--permutations-and-combinations--1',1,'{"question":"When should a permutation be used?","choices":["When only the selected group matters","When no items are selected","When all items must be identical","When the order of selected items matters"],"answer":3,"explanation":""}'::jsonb,'aa860c89448452b00d4097ce908dcb45','official',NULL,NULL,'Permutations and Combinations'),
